/**
 * Loads the JSON artifacts generated by the Python training script.
 * Data is cached in module scope after first fetch.
 */
import { useState, useEffect, useRef } from "react";

const cache = {};

async function fetchJson(path) {
  if (cache[path]) return cache[path];
  const res = await fetch(path);
  if (!res.ok) throw new Error(`Failed to load ${path}: ${res.status}`);
  const data = await res.json();
  cache[path] = data;
  return data;
}

export function useArtifacts() {
  const [state, setState] = useState({ loading: true, error: null, data: null });
  const mounted = useRef(true);

  useEffect(() => {
    mounted.current = true;
    Promise.all([
      fetchJson("/data/dataset_stats.json"),
      fetchJson("/data/model_metrics.json"),
      fetchJson("/data/confusion_matrices.json"),
      fetchJson("/data/feature_importance.json"),
      fetchJson("/data/sample_input.json"),
    // JSON files live in public/data/ — Vite serves them at /data/ in dev and copies to dist/data/ at build.
    ])
      .then(([datasetStats, modelMetrics, confusionMatrices, featureImportance, sampleInput]) => {
        if (!mounted.current) return;
        setState({
          loading: false,
          error: null,
          data: { datasetStats, modelMetrics, confusionMatrices, featureImportance, sampleInput },
        });
      })
      .catch((err) => {
        if (!mounted.current) return;
        setState({ loading: false, error: err.message, data: null });
      });

    return () => { mounted.current = false; };
  }, []);

  return state;
}
